INSERT INTO public.card_translation (card_id, locale_id, lore)
SELECT c.id, l.id, v.lore
FROM (VALUES
    ('EARTH',  'SPAWN',             'es', 'Un pequeño golem de barro que apenas mantiene su forma, pero se aferra tozudamente al suelo.'),
    ('EARTH',  'SPAWN',             'en', 'A tiny mud golem that barely holds its shape, yet clings stubbornly to the ground.'),
    ('WATER',  'SPAWN',             'es', 'Una gota con voluntad propia, curiosa e inofensiva... por ahora.'),
    ('WATER',  'SPAWN',             'en', 'A droplet with a will of its own, curious and harmless... for now.'),
    ('AIR',    'SPAWN',             'es', 'Una brisa apenas perceptible, demasiado débil para sostener nada más que un susurro.'),
    ('AIR',    'SPAWN',             'en', 'A barely perceptible breeze, too weak to carry anything more than a whisper.'),
    ('ETHER',  'SPAWN',             'es', 'Una sombra apenas materializada, mitad aquí, mitad en otro lugar.'),
    ('ETHER',  'SPAWN',             'en', 'A shadow barely made solid, half here, half somewhere else.'),
    ('VOID',   'SPAWN',             'es', 'Un fragmento de la nada que aún no ha decidido qué quiere ser.'),
    ('VOID',   'SPAWN',             'en', 'A fragment of nothingness that has not yet decided what it wants to be.'),
    ('PLASMA', 'SPAWN',             'es', 'Una chispa inestable que apenas logra mantenerse encendida.'),
    ('PLASMA', 'SPAWN',             'en', 'An unstable spark that barely manages to stay lit.'),
    ('FIRE',   'SPAWN',             'es', 'Apenas una llama de vela, pero ya sueña con incendios.'),
    ('FIRE',   'SPAWN',             'en', 'Barely a candle flame, but it already dreams of wildfires.'),
    ('SULFUR', 'SPAWN',             'es', 'Un humo acre que apenas irrita, pero ya insinúa lo corrosivo que puede llegar a ser.'),
    ('SULFUR', 'SPAWN',             'en', 'An acrid smoke that barely irritates, yet already hints at how corrosive it could become.'),
    ('FLESH',  'SPAWN',             'es', 'Un amasijo de tejido apenas formado, tembloroso pero decidido a crecer.'),
    ('FLESH',  'SPAWN',             'en', 'A barely formed mass of tissue, trembling but determined to grow.'),
    ('BLOOD',  'SPAWN',             'es', 'Apenas una gota carmesí, pero ya siente el hambre de algo más grande.'),
    ('BLOOD',  'SPAWN',             'en', 'Barely a crimson drop, but it already feels the hunger for something greater.'),
    ('FUNGI',  'SPAWN',             'es', 'Una espora diminuta que ya busca dónde arraigar.'),
    ('FUNGI',  'SPAWN',             'en', 'A tiny spore already searching for a place to take root.'),
    ('CARBON', 'SPAWN',             'es', 'Una piedra oscura y quebradiza, apenas consciente de su propia dureza.'),
    ('CARBON', 'SPAWN',             'en', 'A dark, brittle stone, barely aware of its own hardness.'),

    ('EARTH',  'HUNTER',            'es', 'Se mueve entre las raíces como si la tierra misma lo guiara hacia su presa.'),
    ('EARTH',  'HUNTER',            'en', 'It moves through the roots as if the earth itself were guiding it toward its prey.'),
    ('WATER',  'HUNTER',            'es', 'Nada en silencio bajo la superficie, esperando el momento exacto para atacar.'),
    ('WATER',  'HUNTER',            'en', 'It swims silently beneath the surface, waiting for the exact moment to strike.'),
    ('AIR',    'HUNTER',            'es', 'Corta el aire antes de que puedas verlo venir.'),
    ('AIR',    'HUNTER',            'en', 'It cuts through the air before you can see it coming.'),
    ('ETHER',  'HUNTER',            'es', 'Se desliza entre planos como quien camina entre habitaciones.'),
    ('ETHER',  'HUNTER',            'en', 'It slips between planes the way one walks between rooms.'),
    ('VOID',   'HUNTER',            'es', 'Donde pisa, por un instante, deja de existir absolutamente nada.'),
    ('VOID',   'HUNTER',            'en', 'Where it treads, for an instant, that ground stops existing altogether.'),
    ('PLASMA', 'HUNTER',            'es', 'Arde con una intensidad que promete mucho más de lo que aún muestra.'),
    ('PLASMA', 'HUNTER',            'en', 'It burns with an intensity that promises far more than it has yet shown.'),
    ('FIRE',   'HUNTER',            'es', 'Persigue a su presa con la misma voracidad con la que consume la madera seca.'),
    ('FIRE',   'HUNTER',            'en', 'It hunts its prey with the same voracity it uses to consume dry wood.'),
    ('SULFUR', 'HUNTER',            'es', 'Corroe lentamente todo lo que toca, sin apuro alguno.'),
    ('SULFUR', 'HUNTER',            'en', 'It slowly corrodes everything it touches, in no hurry at all.'),
    ('FLESH',  'HUNTER',            'es', 'Se regenera tan rápido como se lo hieren, incansable en su persecución.'),
    ('FLESH',  'HUNTER',            'en', 'It regenerates as fast as it is wounded, tireless in its pursuit.'),
    ('BLOOD',  'HUNTER',            'es', 'Sigue el rastro de la vida ajena como si fuera propia.'),
    ('BLOOD',  'HUNTER',            'en', 'It follows the trail of another''s life as if it were its own.'),
    ('FUNGI',  'HUNTER',            'es', 'Se extiende en silencio bajo la superficie, esperando el momento de emerger.'),
    ('FUNGI',  'HUNTER',            'en', 'It spreads silently beneath the surface, waiting for the moment to emerge.'),
    ('CARBON', 'HUNTER',            'es', 'Su superficie corta como cristal, silencioso pero letal.'),
    ('CARBON', 'HUNTER',            'en', 'Its surface cuts like glass, silent but lethal.'),

    ('EARTH',  'ABOMINATION',       'es', 'Una masa de roca viva que aplasta todo lo que se atreve a interponerse en su camino.'),
    ('EARTH',  'ABOMINATION',       'en', 'A mass of living rock that crushes anything that dares stand in its way.'),
    ('WATER',  'ABOMINATION',       'es', 'Arrastra corrientes enteras a su paso, ahogando cualquier resistencia.'),
    ('WATER',  'ABOMINATION',       'en', 'It drags entire currents in its wake, drowning any resistance.'),
    ('AIR',    'ABOMINATION',       'es', 'Un vendaval con forma de bestia, capaz de arrancar árboles de raíz.'),
    ('AIR',    'ABOMINATION',       'en', 'A gale given beastly form, able to tear trees out by their roots.'),
    ('ETHER',  'ABOMINATION',       'es', 'Su presencia dobla el aire a su alrededor, indiferente a las leyes del resto del mundo.'),
    ('ETHER',  'ABOMINATION',       'en', 'Its presence bends the air around it, indifferent to the laws that govern the rest of the world.'),
    ('VOID',   'ABOMINATION',       'es', 'Consume la luz misma, dejando tras de sí un silencio que duele.'),
    ('VOID',   'ABOMINATION',       'en', 'It consumes light itself, leaving behind a silence that hurts.'),
    ('PLASMA', 'ABOMINATION',       'es', 'Un núcleo estelar en miniatura, incapaz de contener su propia furia.'),
    ('PLASMA', 'ABOMINATION',       'en', 'A miniature stellar core, unable to contain its own fury.'),
    ('FIRE',   'ABOMINATION',       'es', 'Un incendio con voluntad propia, que decide cuándo y qué destruir.'),
    ('FIRE',   'ABOMINATION',       'en', 'A wildfire with a will of its own, deciding when and what to destroy.'),
    ('SULFUR', 'ABOMINATION',       'es', 'Respira veneno como otros respiran aire, y lo comparte generosamente.'),
    ('SULFUR', 'ABOMINATION',       'en', 'It breathes poison the way others breathe air, and shares it generously.'),
    ('FLESH',  'ABOMINATION',       'es', 'Una masa viviente que absorbe todo lo que destruye para hacerse más grande.'),
    ('FLESH',  'ABOMINATION',       'en', 'A living mass that absorbs everything it destroys to grow larger.'),
    ('BLOOD',  'ABOMINATION',       'es', 'Se alimenta de cada gota derramada en la batalla, creciendo con cada herida infligida.'),
    ('BLOOD',  'ABOMINATION',       'en', 'It feeds on every drop spilled in battle, growing with each wound it inflicts.'),
    ('FUNGI',  'ABOMINATION',       'es', 'Una colonia entera con una sola voluntad: cubrirlo todo.'),
    ('FUNGI',  'ABOMINATION',       'en', 'An entire colony with a single will: to cover everything.'),
    ('CARBON', 'ABOMINATION',       'es', 'Comprimido por eones de presión, nada en su forma actual puede quebrarlo con facilidad.'),
    ('CARBON', 'ABOMINATION',       'en', 'Compressed by eons of pressure, nothing in its current form can break it easily.'),

    ('EARTH',  'SUPREME_ANCESTRAL', 'es', 'Se dice que las montañas nacieron de su sueño; despertarlo es despertar al mundo entero.'),
    ('EARTH',  'SUPREME_ANCESTRAL', 'en', 'It is said the mountains were born from its dream; to wake it is to wake the entire world.'),
    ('WATER',  'SUPREME_ANCESTRAL', 'es', 'Los océanos le deben su profundidad; ninguna marea se mueve sin su permiso.'),
    ('WATER',  'SUPREME_ANCESTRAL', 'en', 'The oceans owe it their depth; no tide moves without its permission.'),
    ('AIR',    'SUPREME_ANCESTRAL', 'es', 'El primer viento del mundo aún sopla en su interior; ninguna tormenta lo iguala.'),
    ('AIR',    'SUPREME_ANCESTRAL', 'en', 'The world''s first wind still blows within it; no storm can match it.'),
    ('ETHER',  'SUPREME_ANCESTRAL', 'es', 'No pertenece del todo a este mundo, y el mundo lo sabe.'),
    ('ETHER',  'SUPREME_ANCESTRAL', 'en', 'It does not fully belong to this world, and the world knows it.'),
    ('VOID',   'SUPREME_ANCESTRAL', 'es', 'Antes de las estrellas, solo estaba él. Después de ellas, seguirá estando.'),
    ('VOID',   'SUPREME_ANCESTRAL', 'en', 'Before the stars, only it existed. After them, it will still remain.'),
    ('PLASMA', 'SUPREME_ANCESTRAL', 'es', 'Nació del corazón de una estrella moribunda, y hereda toda su ira.'),
    ('PLASMA', 'SUPREME_ANCESTRAL', 'en', 'It was born from the heart of a dying star, and inherits all its fury.'),
    ('FIRE',   'SUPREME_ANCESTRAL', 'es', 'El primer fuego jamás encendido; todos los demás son solo ecos suyos.'),
    ('FIRE',   'SUPREME_ANCESTRAL', 'en', 'The first fire ever lit; every other flame is just an echo of it.'),
    ('SULFUR', 'SUPREME_ANCESTRAL', 'es', 'Donde camina, la tierra misma se disuelve; nada sobrevive a su paso dos veces.'),
    ('SULFUR', 'SUPREME_ANCESTRAL', 'en', 'Where it walks, the ground itself dissolves; nothing survives its passing twice.'),
    ('FLESH',  'SUPREME_ANCESTRAL', 'es', 'Ha muerto tantas veces que ya no recuerda cómo permanecer así.'),
    ('FLESH',  'SUPREME_ANCESTRAL', 'en', 'It has died so many times that it no longer remembers how to stay that way.'),
    ('BLOOD',  'SUPREME_ANCESTRAL', 'es', 'Todo lo que sangra le pertenece, tarde o temprano.'),
    ('BLOOD',  'SUPREME_ANCESTRAL', 'en', 'Everything that bleeds belongs to it, sooner or later.'),
    ('FUNGI',  'SUPREME_ANCESTRAL', 'es', 'Bajo cada bosque del mundo, sus raíces ya han llegado antes que tú.'),
    ('FUNGI',  'SUPREME_ANCESTRAL', 'en', 'Beneath every forest in the world, its roots have already arrived before you.'),
    ('CARBON', 'SUPREME_ANCESTRAL', 'es', 'Forjado en el núcleo de un mundo muerto, es la dureza hecha monstruo.'),
    ('CARBON', 'SUPREME_ANCESTRAL', 'en', 'Forged in the core of a dead world, it is hardness made monster.')
) AS v(element, power_rank, locale, lore)
JOIN public.card c ON c.element = v.element AND c.power_rank = v.power_rank
JOIN public.locale l ON l.code = v.locale
ON CONFLICT (card_id, locale_id) DO UPDATE SET lore = EXCLUDED.lore;
